mapper.select:
SELECT i.id, i.ofertante_id AS ofertanteId, i.contraparte_id AS contraparteId, i.estado_id AS estadoId, i.carta_ofrecer_final_expansion_id AS cartaOfrecerFinalExpansionId, i.carta_ofrecer_final_carta_juego_id AS cartaOfrecerFinalCartaJuegoId, i.carta_querer_final_expansion_id AS cartaQuererFinalExpansionId, i.carta_querer_final_carta_juego_id AS cartaQuererFinalCartaJuegoId, i.fecha_creacion AS fechaCreacion, i.fecha_cambio AS fechaCambio FROM intercambio i
AND i.id = #{id}
AND i.ofertante_id != #{usuarioId}
AND EXISTS ( SELECT 1 FROM carta_intercambio_ofrecer cio JOIN carta c ON c.expansion_id = cio.expansion_id AND c.carta_juego_id = cio.carta_juego_id WHERE cio.intercambio_id = i.id AND c.nombre LIKE CONCAT('%', #{cartasOfrecerNombre}, '%') )
AND EXISTS ( SELECT 1 FROM carta_intercambio_querer ciq JOIN carta c ON c.expansion_id = ciq.expansion_id AND c.carta_juego_id = ciq.carta_juego_id WHERE ciq.intercambio_id = i.id AND c.nombre LIKE CONCAT('%', #{cartasQuererNombre}, '%') )
AND i.estado_id = 1
ORDER BY ${ordenacion}
ORDER BY i.id DESC

mapper.update:
UPDATE intercambio
contraparte_id = #{contraparteId}, estado_id = #{estadoId}, carta_ofrecer_final_expansion_id = #{cartaOfrecerFinalExpansionId}, carta_ofrecer_final_carta_juego_id = #{cartaOfrecerFinalCartaJuegoId}, carta_querer_final_expansion_id = #{cartaQuererFinalExpansionId}, carta_querer_final_carta_juego_id = #{cartaQuererFinalCartaJuegoId}, fecha_cambio = #{fechaCambio}
WHERE id = #{id}

mapper.select:
SELECT i.id, i.ofertante_id AS ofertanteId, i.contraparte_id AS contraparteId, i.estado_id AS estadoId, i.carta_ofrecer_final_expansion_id AS cartaOfrecerFinalExpansionId, i.carta_ofrecer_final_carta_juego_id AS cartaOfrecerFinalCartaJuegoId, i.carta_querer_final_expansion_id AS cartaQuererFinalExpansionId, i.carta_querer_final_carta_juego_id AS cartaQuererFinalCartaJuegoId, i.fecha_creacion AS fechaCreacion, i.fecha_cambio AS fechaCambio FROM intercambio i
AND i.id = #{id}
AND (i.ofertante_id = #{usuarioId} OR i.contraparte_id = #{usuarioId})
AND EXISTS ( SELECT 1 FROM carta_intercambio_ofrecer cio JOIN carta c ON c.expansion_id = cio.expansion_id AND c.carta_juego_id = cio.carta_juego_id WHERE cio.intercambio_id = i.id AND c.nombre LIKE CONCAT('%', #{cartasOfrecerNombre}, '%') )
AND EXISTS ( SELECT 1 FROM carta_intercambio_querer ciq JOIN carta c ON c.expansion_id = ciq.expansion_id AND c.carta_juego_id = ciq.carta_juego_id WHERE ciq.intercambio_id = i.id AND c.nombre LIKE CONCAT('%', #{cartasQuererNombre}, '%') )
AND i.estado_id = #{estadoId}
AND i.estado_id != 4
ORDER BY ${ordenacion}
ORDER BY i.id DESC

